  private async findUpload(d:SqlDatabase,c:WorkspaceContext,companyId:number,deliveryId:string):Promise<WhatsAppOutboundMediaUpload|null> { const row=(await d.query<UploadRow>("SELECT * FROM whatsapp_outbound_media_uploads WHERE workspace_id=? AND company_id=? AND outbound_delivery_id=?",[c.workspaceId,companyId,deliveryId]))[0];return row?upload(row):null; }
  private async findVisibility(c:WorkspaceContext,companyId:number,messageId:string,deliveryId:string,d:SqlDatabase=this.database):Promise<VoiceResponseVisibility|null> { const row=(await d.query<VisibilityRow>("SELECT * FROM voice_response_visibility WHERE workspace_id=? AND company_id=? AND conversation_message_id=? AND outbound_delivery_id=?",[c.workspaceId,companyId,messageId,deliveryId]))[0];return row?visibility(row):null; }
  private async semanticMessages(sql:string,c:WorkspaceContext,companyId:number,limit:number,scoped:boolean):Promise<readonly ConversationMessage[]> { if(!Number.isSafeInteger(limit)||limit<1)return [];const rows=await this.database.query<MessageRow>(sql,scoped?[c.workspaceId,companyId,c.workspaceId,companyId,limit]:[c.workspaceId,companyId,limit]);return Object.freeze(rows.map(message)); }
  private async suppressSynthesis(d:SqlDatabase,id:string,deliveryId:string,at:string):Promise<void> { await d.execute("UPDATE voice_synthesis_requests SET state='suppressed',lease_owner=NULL,lease_expires_at=NULL,safe_outcome='suppressed',safe_failure_category=NULL,completed_at=?,updated_at=? WHERE id=? AND state='leased'",[at,at,id]);await d.execute("UPDATE outbound_deliveries SET state='suppressed',lease_owner=NULL,lease_expires_at=NULL,safe_error_category=NULL,updated_at=? WHERE id=? AND state='blocked_by_synthesis'",[at,deliveryId]); }
  private async uploadAuthority(d:SqlDatabase,c:WorkspaceContext,companyId:number,id:string,owner:string,at:string):Promise<{outbound_delivery_id:string;connection_id:string;media_type:string;allowed:number}|null> { return (await d.query<{outbound_delivery_id:string;connection_id:string;media_type:string;allowed:number}&Record<string,unknown>>("SELECT u.outbound_delivery_id,d.transport_connection_id connection_id,a.media_type,CASE WHEN d.state IN ('pending','retryable') AND d.payload_kind='audio' AND d.response_policy='deferred_voice' AND d.media_asset_id=u.media_asset_id AND cc.state='automated' AND cc.authority_generation=d.expected_authority_generation AND p.voice_ai_enabled=1 AND p.audio_response_mode='voice_with_text_fallback' THEN 1 ELSE 0 END allowed FROM whatsapp_outbound_media_uploads u JOIN outbound_deliveries d ON d.id=u.outbound_delivery_id JOIN provider_message_records r ON r.id=d.provider_message_record_id JOIN media_assets a ON a.id=u.media_asset_id JOIN whatsapp_voice_policies p ON p.whatsapp_connection_id=d.transport_connection_id LEFT JOIN conversation_controls cc ON cc.conversation_id=(SELECT conversation_id FROM conversation_messages WHERE id=r.conversation_message_id) WHERE u.id=? AND u.workspace_id=? AND u.company_id=? AND u.state='uploading' AND u.lease_owner=? AND u.lease_expires_at>?",[id,c.workspaceId,companyId,owner,at]))[0]??null; }
  private async suppressUpload(d:SqlDatabase,id:string,at:string):Promise<void> { await d.execute("UPDATE whatsapp_outbound_media_uploads SET state='failed',provider_media_id=NULL,safe_error_category='suppressed',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=?",[at,id]);await d.execute("UPDATE outbound_deliveries SET state='suppressed',lease_owner=NULL,lease_expires_at=NULL,safe_error_category=NULL,updated_at=? WHERE id=(SELECT outbound_delivery_id FROM whatsapp_outbound_media_uploads WHERE id=?) AND state IN ('pending','retryable')",[at,id]); }
  private async readRow(c:WorkspaceContext,companyId:number,conversationId:string,messageId:string):Promise<ReadRow|null> { const sql="SELECT m.direction,t.normalized_transcript,t.language_tag,t.outcome transcript_outcome,tr.state transcription_state,d.response_policy,d.state delivery_state,d.payload_kind,s.state synthesis_state,u.state upload_state,CASE WHEN m.direction='inbound' THEN (SELECT a.id FROM whatsapp_inbound_media i JOIN media_assets a ON a.id=i.media_asset_id WHERE i.conversation_message_id=m.id AND i.workspace_id=? AND i.company_id=? AND i.provider_kind='audio' AND i.state='associated' AND a.kind='audio' AND a.status='ready' AND a.deleted_at IS NULL LIMIT 1) ELSE (SELECT a.id FROM media_assets a WHERE a.id=d.media_asset_id AND a.kind='audio' AND a.status='ready' AND a.deleted_at IS NULL LIMIT 1) END playback_asset_id,CASE WHEN m.direction='inbound' THEN (SELECT a.media_type FROM whatsapp_inbound_media i JOIN media_assets a ON a.id=i.media_asset_id WHERE i.conversation_message_id=m.id AND i.workspace_id=? AND i.company_id=? AND i.provider_kind='audio' AND i.state='associated' AND a.kind='audio' AND a.status='ready' AND a.deleted_at IS NULL LIMIT 1) ELSE (SELECT a.media_type FROM media_assets a WHERE a.id=d.media_asset_id AND a.kind='audio' AND a.status='ready' AND a.deleted_at IS NULL LIMIT 1) END playback_media_type,CASE WHEN EXISTS(SELECT 1 FROM whatsapp_inbound_media i JOIN channel_provider_events e ON e.id=i.channel_provider_event_id JOIN channel_execution_requests r ON r.channel_provider_event_id=e.id WHERE i.conversation_message_id=m.id AND i.workspace_id=? AND i.company_id=? AND i.provider_kind='audio' AND r.state='unsupported' AND r.outcome='unsupported') THEN 1 ELSE 0 END unsupported FROM conversation_messages m JOIN conversations cn ON cn.id=m.conversation_id JOIN companies co ON co.id=cn.company_id LEFT JOIN conversation_audio_transcripts t ON t.conversation_message_id=m.id AND t.workspace_id=? AND t.company_id=? LEFT JOIN audio_transcription_requests tr ON tr.conversation_message_id=m.id AND tr.workspace_id=? AND tr.company_id=? LEFT JOIN provider_message_records p ON p.conversation_message_id=m.id AND p.direction='outbound' AND p.communication_channel='whatsapp' LEFT JOIN outbound_deliveries d ON d.provider_message_record_id=p.id LEFT JOIN voice_synthesis_requests s ON s.outbound_delivery_id=d.id AND s.workspace_id=? AND s.company_id=? LEFT JOIN whatsapp_outbound_media_uploads u ON u.outbound_delivery_id=d.id AND u.workspace_id=? AND u.company_id=? WHERE m.id=? AND m.conversation_id=? AND co.workspace_id=? AND co.id=?";const row=(await this.database.query<ReadRow>(sql,[c.workspaceId,companyId,c.workspaceId,companyId,c.workspaceId,companyId,c.workspaceId,companyId,c.workspaceId,companyId,c.workspaceId,companyId,messageId,conversationId,c.workspaceId,companyId]))[0];return row??null; }
